const input = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const userPrompt = String(input.userPrompt || input.prompt || '');
const locale = input.locale === 'es' ? 'es' : 'en';
const role = input.role ? String(input.role) : undefined;
const projectId = input.projectId ? String(input.projectId) : undefined;
const route = input.route ? String(input.route) : undefined;
const context = input.context && typeof input.context === 'object' ? input.context : {};
const rawMessages = Array.isArray(input.messages) ? input.messages : [];
const recentMessages = rawMessages.slice(-6).map(m => ({
  role: m.role,
  content: typeof m.content === 'string' ? m.content.slice(0, 300) : String(m.content || '')
}));
const tools = (Array.isArray(input.tools) ? input.tools : []).map(t => ({
  name: t.name,
  description: t.description,
  category: t.category,
  parameters: t.parameters
}));
const promptPayload = {
  locale,
  role,
  projectId,
  route,
  userPrompt,
  bimContext: context,
  recentMessages,
  availableTools: tools
};
return [{
  json: {
    userPrompt,
    locale,
    role,
    projectId,
    route,
    context,
    recentMessages,
    tools,
    promptText: JSON.stringify(promptPayload, null, 2)
  }
}];

const raw = $json.text ?? $json.output ?? $json.response ?? $json;
let parsed = raw;
if (typeof raw === 'string') { try { parsed = JSON.parse(raw); } catch { parsed = { message: raw }; } }
const message = parsed && typeof parsed.message === 'string' ? parsed.message : 'The remote assistant returned no message.';
const toolCalls = parsed && Array.isArray(parsed.toolCalls) ? parsed.toolCalls : undefined;
return [{ json: toolCalls ? { message, toolCalls } : { message } }];
